// ----- CLI parsing -----
function parseArgs(argv: string[]): string[] {
  // Accept: --groups g1 g2 ...  (groups are positional values after --groups, until end / next flag)
  const groups: string[] = [];
  let i = 0;
  while (i < argv.length) {
    const a = argv[i];
    if (a === '--groups' || a === '--group') {
      i++;
      while (i < argv.length && !argv[i].startsWith('--')) {
        groups.push(argv[i]);
        i++;
      }
    } else {
      i++;
    }
  }
  return groups;
}

